from decimal import Decimal


def _field(record: dict | None, name: str) -> object:
    """Return a field value, treating absent records and fields as empty strings."""
    if record is None:
        return ""
    return record.get(name, "")


def _numeric(value: object) -> Decimal:
    """Apply the legacy numeric-context coercion for empty values."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    """Implement legacy LOOKUP, including live-row filtering and first-match order."""
    if tables is None:
        return ""

    rows = tables.get(table_name, ())
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order record using the legacy VRL rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            if not (disc_pct >= Decimal(0) and disc_pct <= Decimal(100)):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        if event == "UPDATE":
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            if disc_pct > Decimal(20):
                role_id = _lookup(
                    tables,
                    "USR_MASTER",
                    "USR_ID",
                    _field(record, "OWNER_UID"),
                    "ROLE_ID",
                )
                if role_id != "MGR" and role_id != "ADMIN":
                    errors.append(
                        {
                            "code": "E5002",
                            "message": "Discount over 20 percent requires manager role",
                            "severity": "BLOCK",
                        }
                    )

        if event == "UPDATE":
            old_stat_cd = _field(old, "STAT_CD")
            stat_cd = _field(record, "STAT_CD")
            if old_stat_cd == "I" and stat_cd != "I" and stat_cd != "X":
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            qty = _numeric(_field(record, "QTY"))
            if not qty > Decimal(0):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        if event == "INSERT":
            active_flg = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _field(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flg != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
